{
 "doc1_email_thread_may": [
  {
   "from": "Deborah Fairweather",
   "sent": "2026-05-04 10:12",
   "text": "I was scammed by a man calling himself Sgt. Aaron Pike whom I met on Facebook in February. He said he needed money for a satellite phone and leave papers. I used your Beacon Coin kiosk at the Kwik Fill on Peach St on March 28 (my first time ever using one), April 9 and May 1. I reported it to the Erie County Sheriff's Office this morning, report SO-26-11873. He still messages me every day; I haven't replied. Please refund my money."
  },
  {
   "from": "Beacon Coin Support",
   "sent": "2026-05-06 14:47",
   "text": "Dear Ms. Fairweather, under Section 12.4 of our Terms of Service, fraud claims must be reported within 72 hours of the transaction. Your report of May 4 was received after this period for all three transactions. Your claim is therefore denied."
  }
 ],
 "doc2_regulator_letter": {
  "date": "2026-05-20",
  "from": "State Department of Banking - Consumer Affairs Unit",
  "to": "Beacon Coin LLC (copy to complainant)",
  "text": "The Department has received a complaint from Ms. Deborah Fairweather concerning three kiosk transactions. Under the Virtual Currency Kiosk Act, a 'new customer' is a customer during the 30 days following that customer's first transaction with the operator. A new customer who was fraudulently induced to make a transaction is entitled to a refund of the full amount of that transaction, including fees, if the customer notifies the operator and a law enforcement agency within 90 days of the transaction. Contract terms that set a shorter reporting period are not enforceable against this right. Please review Ms. Fairweather's complaint under the Act and provide the Department with a written response within 15 business days."
 },
 "doc3_operator_revised_decision": {
  "date": "2026-06-03",
  "from": "Beacon Coin LLC - Compliance",
  "text": "Following further review, Beacon Coin has reversed its May 6 decision in part. Transactions BC-118204 (March 28, cash $1,800.00) and BC-121977 (April 9, cash $2,000.00) were made during your new-customer period and will be refunded in full, including fees: $3,800.00 by check, mailed June 5. Transaction BC-126310 (May 1, cash $2,000.00) took place 34 days after your first transaction and is not eligible under the Act. This refund is made without admission of liability."
 },
 "doc4_customer_email_june": {
  "sent": "2026-06-18 09:30",
  "from": "Deborah Fairweather",
  "text": "I received your check on June 10 and deposited it - thank you. But I'm still out the $2,000 from May 1. Aaron finally stopped texting me after I sent him a photo of the sheriff's report on June 12. Is there any other way to get the last $2,000 back?"
 }
}
